exploreUrl:
@js:
var period = { '热榜': 'hour', '日榜': 'day', '周榜': 'week', '月榜': 'month' };
var sorts = { '最新': 'date', '阅读量': 'view', '收藏数': 'like', '字数': 'char' };
var rank = String(infoMap['榜单周期'] || '热榜');
var sort = String(infoMap['文章排序'] || '最新');
var tagPage = Number(infoMap['标签页'] || 1);
if (!isFinite(tagPage) || tagPage < 1 || Math.floor(tagPage) !== tagPage) tagPage = 1;
var rows = [
    { title: '榜单周期', type: 'select', chars: ['热榜', '日榜', '周榜', '月榜'], default: rank, action: 'java.refreshExplore()' },
    { title: '文章排序', type: 'select', chars: ['最新', '阅读量', '收藏数', '字数'], default: sort, action: 'java.refreshExplore()' },
    { title: '榜单', url: '/rank?type=' + (period[rank] || 'hour') + '&p={{page}}' },
    { title: '文章', url: '/n?sort=' + (sorts[sort] || 'date') + '&p={{page}}' },
    { title: '标签页', type: 'text', default: String(tagPage) },
    { title: '载入标签', type: 'button', action: 'java.refreshExplore()' }
];
var tagUrl = String(source.getKey()) + '/tag?sort=pop&p=' + tagPage;
var response = hlibVerifiedResponse(java.connect(tagUrl), tagUrl, java, source);
var doc = org.jsoup.Jsoup.parse(String(response.body()));
var links = doc.select("div.col > a[href^='/tag/']");
for (var i = 0; i < links.size(); i++) {
    var a = links.get(i);
    rows.push({ title: String(a.text()), url: String(a.attr('href')) + '?sort=' + (sorts[sort] || 'date') + '&p={{page}}' });
}
if (tagPage > 1) rows.push({ title: '上一页标签', type: 'button', action: "infoMap['标签页']='" + (tagPage - 1) + "';java.refreshExplore()" });
if (!doc.select("button[aria-label='后一页']:not([disabled])").isEmpty()) {
    rows.push({ title: '下一页标签', type: 'button', action: "infoMap['标签页']='" + (tagPage + 1) + "';java.refreshExplore()" });
}
JSON.stringify(rows);

jsLib:
function hlibVerifiedResponse(response, target, java, source) {
    function challenge(r) {
        return /_cf_chl_opt|<title>\s*人机校验\s*<\/title>/.test(String(r.body() || ''));
    }
    function login(r) {
        var html = String(r.body() || '');
        return /href=["']\/login["']/.test(html) && !/href=["']\/logout["']/.test(html);
    }
    if (challenge(response)) {
        response = java.startBrowserAwait(target, 'H图书馆：完成验证后点确认', false);
    }
    if (login(response)) {
        java.startBrowserAwait(String(source.getKey()) + '/login', 'H图书馆：登录后点确认', false);
        var options = /\/search\?/.test(target) ? ',' + JSON.stringify({
            webView: true,
            webJs: "(window._cf_chl_opt || location.pathname === '/antibot' || location.pathname === '/login' || document.querySelector('#loading.d-none')) ? document.documentElement.outerHTML : null"
        }) : '';
        response = java.connect(target + options);
        if (challenge(response)) {
            response = java.startBrowserAwait(target, 'H图书馆：完成验证后点确认', false);
        }
    }
    if (challenge(response)) throw 'H图书馆：人机验证尚未完成';
    if (login(response)) throw 'H图书馆：网站账号尚未登录';
    return response;
}
